record.field:
answer = payload or {}
result = answer.get('result') or {}
service = record.x_service_id
if 'balance' in answer:
    service.write({'x_balance': answer.get('balance') or 0})
# Credit usage: an older server sends no cost; the history then starts with its update
usage = {}
if 'cost' in answer:
    usage['x_cost'] = answer.get('cost') or 0
if 'balance' in answer:
    usage['x_balance_after'] = answer.get('balance') or 0
if usage:
    record.write(usage)
if answer.get('state') != 'done':
    record.write({'x_state': 'error', 'x_error': answer.get('error') or 'error', 'x_result': str(answer)})
elif record.x_kind == 'register' and not result.get('account_token'):
    # An incomplete answer never removes the token of a service that works
    record.write({'x_state': 'error', 'x_error': 'The answer has no account token', 'x_result': str(answer)})
elif record.x_kind == 'register':
    token = result.get('account_token')
    service.write({'x_token': token})
    if service.x_send_action_id:
        service.x_send_action_id.write({
            'webhook_url': service.x_server.rstrip('/') + '/iap_online/' + service.x_code + '?token=' + token,
        })
    record.write({'x_state': 'done', 'x_error': False, 'x_result': 'Service activated'})
elif record.x_kind == 'balance' or not service.x_apply_action_id:
    record.write({'x_state': 'done', 'x_error': False, 'x_result': str(result)})
else:
    # The service module writes the answer on its document, and the state of the request
    service.x_apply_action_id.with_context(
        active_id=record.id, active_ids=record.ids, active_model='x_iap_online_request', iap_answer=answer,
    ).run()
    if record.x_state == 'sent':
        record.write({'x_state': 'done', 'x_result': str(result)})
